begin;
create table if not exists public.angelcare_marketplace_finance_price_books(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('PB-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))),name text not null,territory_id uuid,currency_label text not null,market_segment text not null,customer_type text not null,valid_from date not null,valid_until date,status text not null default 'draft' check(status in('draft','financial_review','commercial_review','approval_pending','approved','scheduled','active','superseded','suspended','expired','archived')),version int not null default 1,owner_id uuid,finance_owner_id uuid,currency_valid boolean not null default true,approved_by uuid,approved_at timestamptz,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(name,territory_id,version));
create table if not exists public.angelcare_marketplace_finance_price_book_versions(id uuid primary key default gen_random_uuid(),price_book_id uuid not null references public.angelcare_marketplace_finance_price_books(id) on delete cascade,version int not null,snapshot jsonb not null,change_reason text,created_by uuid,created_at timestamptz not null default now(),unique(price_book_id,version));
create table if not exists public.angelcare_marketplace_finance_price_rules(id uuid primary key default gen_random_uuid(),price_book_id uuid not null references public.angelcare_marketplace_finance_price_books(id) on delete cascade,source_object_type text not null,source_object_id uuid,catalog_item_id uuid,pricing_model text not null check(pricing_model in('fixed','hourly','daily','per_child','per_employee','per_room','per_site','per_session','per_learner','per_assessment','subscription','usage_based','tiered','package','custom_approved')),unit_label text,minimum_price numeric(16,2),standard_price numeric(16,2) not null,maximum_price numeric(16,2),cost_basis numeric(16,2),target_margin numeric(8,3),floor_margin numeric(8,3),maximum_discount numeric(8,3),commission_rate numeric(8,3),territory_id uuid,status text not null default 'draft',created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_finance_revenue_streams(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('REV-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,11))),stream_type text not null,source_object_type text not null,source_object_id uuid not null,territory_id uuid,tenant_id uuid,organization_id uuid,family_account_id uuid,price_book_id uuid references public.angelcare_marketplace_finance_price_books(id),price_book_version int,price_rule_id uuid references public.angelcare_marketplace_finance_price_rules(id),currency_label text not null,gross_amount numeric(16,2) not null default 0,discount_amount numeric(16,2) not null default 0,commission_amount numeric(16,2) not null default 0,provider_payable_amount numeric(16,2) not null default 0,cost_basis numeric(16,2) not null default 0,net_amount numeric(16,2) not null default 0,margin_amount numeric(16,2) not null default 0,margin_rate numeric(8,3) not null default 0,margin_risk boolean not null default false,status text not null default 'quoted' check(status in('quoted','contracted','scheduled','delivered','validated','invoice_ready','invoiced','partially_paid','paid','disputed','cancelled','credited','written_off')),commercial_owner_id uuid,finance_owner_id uuid,recognized_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(source_object_type,source_object_id,stream_type));
create table if not exists public.angelcare_marketplace_finance_margin_rules(id uuid primary key default gen_random_uuid(),rule_key text unique not null,territory_id uuid,stream_type text,customer_type text,minimum_margin numeric(8,3) not null,approval_threshold numeric(8,3),approver_role text not null,status text not null default 'active',valid_from date not null default current_date,valid_until date,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_finance_margin_exceptions(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('MEX-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,11))),source_object_type text not null,source_object_id uuid not null,territory_id uuid,currency_label text not null,configured_price numeric(16,2) not null,proposed_price numeric(16,2) not null,cost_basis numeric(16,2) not null,floor_margin numeric(8,3) not null,proposed_margin numeric(8,3) not null,discount_rate numeric(8,3) not null,reason text not null,status text not null default 'pending' check(status in('pending','approved','rejected','expired','cancelled')),requested_by uuid not null,reviewed_by uuid,reviewed_at timestamptz,decision_reason text,created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_finance_commission_configurations(id uuid primary key default gen_random_uuid(),configuration_key text unique not null,territory_id uuid,source_type text not null,recipient_type text not null,calculation_model text not null,rate numeric(8,3),fixed_amount numeric(16,2),maximum_amount numeric(16,2),valid_from date not null,valid_until date,status text not null default 'active',approved_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_finance_invoice_readiness(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('INVREADY-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))),revenue_stream_id uuid references public.angelcare_marketplace_finance_revenue_streams(id),source_object_type text not null,source_object_id uuid not null,territory_id uuid,tenant_id uuid,currency_label text not null,amount numeric(16,2) not null,status text not null default 'blocked' check(status in('not_evaluated','blocked','evidence_required','validation_required','ready','invoiced','cancelled')),required_evidence text[] not null default '{}',missing_evidence text[] not null default '{}',blockers text[] not null default '{}',finance_owner_id uuid,ready_at timestamptz,invoiced_reference text,updated_at timestamptz not null default now(),unique(source_object_type,source_object_id));
create table if not exists public.angelcare_marketplace_finance_reconciliation_events(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('REC-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,11))),event_type text not null,source_system text not null,source_reference text not null,target_system text not null,target_reference text,territory_id uuid,tenant_id uuid,currency_label text not null,expected_amount numeric(16,2) not null,observed_amount numeric(16,2) not null,difference_amount numeric(16,2) generated always as (observed_amount-expected_amount) stored,status text not null default 'pending' check(status in('pending','matched','exception','under_review','resolved','cancelled')),owner_id uuid,resolution_note text,created_at timestamptz not null default now(),resolved_at timestamptz);
alter table public.angelcare_marketplace_finance_revenue_streams add column if not exists price_book_version int;
create or replace function public.angelcare_marketplace_transition_price_book(p_price_book_id uuid,p_next_status text,p_reason text,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare r public.angelcare_marketplace_finance_price_books;begin if p_next_status='active' and exists(select 1 from public.angelcare_marketplace_finance_price_books b join public.angelcare_marketplace_finance_price_books c on c.id=p_price_book_id where b.id<>c.id and b.status='active' and b.territory_id is not distinct from c.territory_id and b.market_segment=c.market_segment and b.customer_type=c.customer_type) then raise exception 'An active price book already covers this scope';end if;update public.angelcare_marketplace_finance_price_books set status=p_next_status,approved_by=case when p_next_status='approved' then p_actor_id else approved_by end,approved_at=case when p_next_status='approved' then now() else approved_at end,updated_by=p_actor_id,updated_at=now() where id=p_price_book_id returning * into r;if r.id is null then raise exception 'Price book introuvable';end if;return to_jsonb(r);end$$;
create or replace function public.angelcare_marketplace_decide_margin_exception(p_exception_id uuid,p_decision text,p_reason text,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare r public.angelcare_marketplace_finance_margin_exceptions;begin if p_decision not in('approved','rejected') then raise exception 'Invalid decision';end if;update public.angelcare_marketplace_finance_margin_exceptions set status=p_decision,reviewed_by=p_actor_id,reviewed_at=now(),decision_reason=p_reason where id=p_exception_id and status='pending' returning * into r;if r.id is null then raise exception 'Pending exception introuvable';end if;return to_jsonb(r);end$$;
create or replace function public.angelcare_marketplace_evaluate_financial_rule(p_price_rule_id uuid,p_territory_currency text,p_proposed_margin numeric,p_discount_rate numeric,p_exception_approved boolean) returns jsonb language plpgsql security definer set search_path=public as $$declare r public.angelcare_marketplace_finance_price_rules;b public.angelcare_marketplace_finance_price_books;blockers text[]:='{}';begin select * into r from public.angelcare_marketplace_finance_price_rules where id=p_price_rule_id;select * into b from public.angelcare_marketplace_finance_price_books where id=r.price_book_id;if r.id is null or b.id is null then raise exception 'Price rule or price book introuvable';end if;if b.currency_label<>p_territory_currency then blockers:=array_append(blockers,'Territory currency mismatch');end if;if b.status<>'active' or r.status<>'active' then blockers:=array_append(blockers,'Price book or rule is not active');end if;if b.valid_from>current_date or (b.valid_until is not null and b.valid_until<current_date) then blockers:=array_append(blockers,'Price book outside validity window');end if;if p_proposed_margin<coalesce(r.floor_margin,0) and not p_exception_approved then blockers:=array_append(blockers,'Margin floor exception required');end if;if p_discount_rate>coalesce(r.maximum_discount,0) and not p_exception_approved then blockers:=array_append(blockers,'Maximum authorized discount exceeded');end if;if cardinality(blockers)>0 then raise exception 'Commercial rule blocked: %',array_to_string(blockers,'; ');end if;return jsonb_build_object('eligible',true,'priceRuleId',r.id,'priceBookId',b.id,'priceBookVersion',b.version,'territoryCurrency',p_territory_currency);end$$;
create or replace function public.angelcare_marketplace_evaluate_invoice_readiness(p_source_type text,p_source_id uuid,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare r public.angelcare_marketplace_finance_revenue_streams;ready public.angelcare_marketplace_finance_invoice_readiness;missing text[]:='{}';blocks text[]:='{}';state text;begin select * into r from public.angelcare_marketplace_finance_revenue_streams where source_object_type=p_source_type and source_object_id=p_source_id;if r.id is null then raise exception 'Revenue stream introuvable';end if;if r.status not in('delivered','validated','invoice_ready') then blocks:=array_append(blocks,'Source delivery not validated');end if;if r.price_book_id is null or r.price_rule_id is null then missing:=array_append(missing,'Price-book lineage');end if;if r.margin_risk then blocks:=array_append(blocks,'Margin exception unresolved');end if;state:=case when cardinality(blocks)>0 then 'blocked' when cardinality(missing)>0 then 'evidence_required' else 'ready' end;insert into public.angelcare_marketplace_finance_invoice_readiness(revenue_stream_id,source_object_type,source_object_id,territory_id,tenant_id,currency_label,amount,status,required_evidence,missing_evidence,blockers,finance_owner_id,ready_at) values(r.id,p_source_type,p_source_id,r.territory_id,r.tenant_id,r.currency_label,r.net_amount,state,array['Price-book lineage','Delivery validation']::text[],missing,blocks,r.finance_owner_id,case when state='ready' then now() else null end) on conflict(source_object_type,source_object_id) do update set status=excluded.status,missing_evidence=excluded.missing_evidence,blockers=excluded.blockers,ready_at=excluded.ready_at,updated_at=now() returning * into ready;return to_jsonb(ready);end$$;
insert into public.angelcare_marketplace_permissions(permission_key,name,category,sensitive) values ('marketplace.finance.view','Consulter Finance Authority','Finance',false),('marketplace.finance.price_books.manage','Gérer les price books','Finance',true),('marketplace.finance.price_books.approve','Approuver les price books','Finance',true),('marketplace.finance.margins.view','Consulter les marges','Finance',false),('marketplace.finance.exceptions.approve','Approuver les exceptions','Finance',true),('marketplace.finance.revenue.view','Consulter les revenue streams','Finance',false),('marketplace.finance.reconciliation.manage','Gérer les rapprochements','Finance',true),('marketplace.finance.export','Exporter Finance','Finance',true) on conflict(permission_key) do update set name=excluded.name,category=excluded.category,sensitive=excluded.sensitive;
insert into public.angelcare_marketplace_role_permissions(role_key,permission_key) select r.role_key,p.permission_key from public.angelcare_marketplace_roles r cross join public.angelcare_marketplace_permissions p where r.role_key in('marketplace_super_admin','marketplace_executive') and p.permission_key like 'marketplace.finance.%' on conflict do nothing;
insert into public.angelcare_marketplace_modules(module_key,name,description,route_prefix,module_type,audience,status,enabled,required_permissions,required_dependencies,territory_aware,tenant_aware,locale_aware,health_status,owner_role,introduced_by_mega_zip) values('finance-authority','Finance Configuration Authority','Price books, revenue, margin, invoice readiness and reconciliation.','/angelcare-marketplace/admin/finance','authority',array['admin','executive','tenant']::text[],'enabled',true,array['marketplace.finance.view']::text[],array['marketplace-core','commercial-pipeline','operations-execution']::text[],true,true,true,'healthy','finance_director',20) on conflict(module_key) do update set status='enabled',enabled=true,route_prefix=excluded.route_prefix,required_permissions=excluded.required_permissions,updated_at=now();
insert into public.angelcare_marketplace_feature_flags(flag_key,name,description,enabled,status,reason) values('marketplace.finance-authority.enabled','Finance Authority','Price books, margin and invoice readiness.',true,'active','Ultra Delivery 5/5 · Original MZ20') on conflict(flag_key) do update set enabled=true,status='active',reason=excluded.reason,updated_at=now();
alter table public.angelcare_marketplace_finance_price_books enable row level security;
alter table public.angelcare_marketplace_finance_price_book_versions enable row level security;
alter table public.angelcare_marketplace_finance_price_rules enable row level security;
alter table public.angelcare_marketplace_finance_revenue_streams enable row level security;
alter table public.angelcare_marketplace_finance_margin_rules enable row level security;
alter table public.angelcare_marketplace_finance_margin_exceptions enable row level security;
alter table public.angelcare_marketplace_finance_commission_configurations enable row level security;
alter table public.angelcare_marketplace_finance_invoice_readiness enable row level security;
alter table public.angelcare_marketplace_finance_reconciliation_events enable row level security;
revoke all on table public.angelcare_marketplace_finance_price_books,public.angelcare_marketplace_finance_price_book_versions,public.angelcare_marketplace_finance_price_rules,public.angelcare_marketplace_finance_revenue_streams,public.angelcare_marketplace_finance_margin_rules,public.angelcare_marketplace_finance_margin_exceptions,public.angelcare_marketplace_finance_commission_configurations,public.angelcare_marketplace_finance_invoice_readiness,public.angelcare_marketplace_finance_reconciliation_events from anon,authenticated;
grant all on table public.angelcare_marketplace_finance_price_books,public.angelcare_marketplace_finance_price_book_versions,public.angelcare_marketplace_finance_price_rules,public.angelcare_marketplace_finance_revenue_streams,public.angelcare_marketplace_finance_margin_rules,public.angelcare_marketplace_finance_margin_exceptions,public.angelcare_marketplace_finance_commission_configurations,public.angelcare_marketplace_finance_invoice_readiness,public.angelcare_marketplace_finance_reconciliation_events to service_role;
grant execute on function public.angelcare_marketplace_transition_price_book(uuid,text,text,uuid),public.angelcare_marketplace_decide_margin_exception(uuid,text,text,uuid),public.angelcare_marketplace_evaluate_financial_rule(uuid,text,numeric,numeric,boolean),public.angelcare_marketplace_evaluate_invoice_readiness(text,uuid,uuid) to service_role;
create index if not exists ac_price_book_scope_idx on public.angelcare_marketplace_finance_price_books(territory_id,status,valid_from,valid_until);create index if not exists ac_revenue_scope_idx on public.angelcare_marketplace_finance_revenue_streams(territory_id,tenant_id,status,created_at);create index if not exists ac_invoice_readiness_scope_idx on public.angelcare_marketplace_finance_invoice_readiness(territory_id,tenant_id,status,updated_at);
commit;
